contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address asset, uint256 depositAmount) public payable {
        require(asset != address(0) && asset != address(c) && depositAmount > 0);
        require(!c.paused());

        address lrtConfig = c.lrtConfig();
        require(lrtConfig != address(0));

        (bool okAsset, bytes memory assetData) = lrtConfig.staticcall(
            abi.encodeWithSignature("isSupportedAsset(address)", asset)
        );
        require(okAsset && assetData.length >= 32 && abi.decode(assetData, (bool)));

        (bool okLimit, bytes memory limitData) = address(c).staticcall(
            abi.encodeWithSignature("getAssetCurrentLimit(address)", asset)
        );
        require(okLimit && limitData.length >= 32);
        uint256 currentLimit = abi.decode(limitData, (uint256));
        require(depositAmount <= currentLimit);

        (bool okBefore, bytes memory beforeData) = asset.staticcall(
            abi.encodeWithSignature("balanceOf(address)", address(c))
        );
        require(okBefore && beforeData.length >= 32);
        uint256 beforeBalance = abi.decode(beforeData, (uint256));

        bool succeeded;
        try c.depositAsset(asset, depositAmount) {
            succeeded = true;
        } catch {
            succeeded = false;
        }

        (bool okAfter, bytes memory afterData) = asset.staticcall(
            abi.encodeWithSignature("balanceOf(address)", address(c))
        );
        require(okAfter && afterData.length >= 32);
        uint256 afterBalance = abi.decode(afterData, (uint256));

        assert(succeeded && afterBalance == beforeBalance + depositAmount);
    }

    receive() external payable {}
}

