contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address asset, uint256 amount) public {
        require(amount > 0, "amount must be > 0");
        require(c.getAssetCurrentLimit(asset) >= amount, "deposit amount exceeds current limit");

        uint256 expectedRsethMint = c.getRsETHAmountToMint(asset, amount);

        (bool success, bytes memory returndata) = address(c).call(
            abi.encodeWithSignature("depositAsset(address,uint256)", asset, amount)
        );
        require(success, "depositAsset call failed");

        bool found;
        uint256 observedRsethMint;
        if (returndata.length >= 96) {
            bytes32 topic0;
            bytes32 topic1;
            bytes32 topic2;
            assembly {
                topic0 := mload(add(returndata, 32))
                topic1 := mload(add(returndata, 64))
                topic2 := mload(add(returndata, 96))
            }
            if (topic0 == keccak256("AssetDeposit(address,uint256,uint256)") && uint256(topic1) == uint256(uint160(asset))) {
                found = true;
                observedRsethMint = uint256(topic2);
            }
        }

        assert(found && observedRsethMint == expectedRsethMint);
    }

    receive() external payable {}
}

