contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address asset, uint256 amount) public payable {
        require(asset != address(0));

        bool supported;
        supported = c.lrtConfig().isSupportedAsset(asset);
        require(supported);

        // Pre-read the quote using only public/external view calls.
        uint256 quotedRsEth;
        quotedRsEth = c.getRsETHAmountToMint(asset, amount);

        // Read observable state required by the rule.
        uint256 assetBalanceBefore;
        assetBalanceBefore = IERC20(asset).balanceOf(address(c));

        bool reverted;
        try c.depositAsset(asset, amount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // If the deposit succeeded, the contract must have moved exactly `amount`
        // of `asset` into itself (the token transfer is the observable, general
        // effect of the call).  Alternatively, a revert is acceptable whenever the
        // amount is zero or exceeds the current deposit limit, or when the token
        // transfer fails.
        if (!reverted) {
            uint256 assetBalanceAfter;
            assetBalanceAfter = IERC20(asset).balanceOf(address(c));
            assert(assetBalanceAfter >= assetBalanceBefore);
            assert(assetBalanceAfter - assetBalanceBefore == amount);
            assert(quotedRsEth > 0 || amount == 0);
        } else {
            // The general revert condition: the contract must revert if the input
            // amount is zero or larger than the current deposit limit (assuming
            // the asset is supported and the token transfer would otherwise not
            // revert with a different reason during this test setup).
            assert(amount == 0 || amount > c.getAssetCurrentLimit(asset));
        }
    }

    receive() external payable {}
}

