            reverted = true;
        }
        // General rule: whenever the deposit succeeds, the amount of rsETH
        // computed by the public pricing function must be the amount minted
        // to the depositor; equivalently, the total supply of rsETH grows by
        // exactly that computed amount. Using the rsETH contract's own
        // totalSupply through the public getter is observable only if rsETH
        // is set; otherwise the call reverts and no rule is asserted.
        if (!reverted) {
            address rsethAddr = c.lrtConfig().rsETH();
            uint256 supplyAfter = IERC20(rsethAddr).totalSupply();
            assert(supplyAfter - supplyBefore == expectedMint);
        } else {
            // If the call reverted, no assertion is required; still reachable.
            assert(reverted);
        }
    }
}

