contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address asset, uint256 depositAmount) public {
        // The caller of depositAsset is this test contract, so it must hold enough of the asset.
        // Require a non-zero deposit that fits within the current deposit limit.
        uint256 currentLimit = c.getAssetCurrentLimit(asset);
        require(depositAmount > 0 && depositAmount <= currentLimit, "limit");

        // Read the expected rsETH amount before the call.
        uint256 expectedMint = c.getRsETHAmountToMint(asset, depositAmount);

        // We cannot easily mint arbitrary ERC20 assets here; instead we rely on the current
        // asset balance of this test contract being sufficient. For the rule to hold for
        // every input, we must ensure the transferFrom does not fail.
        // Approve and ensure balance.
        IERC20(asset).approve(address(c), depositAmount);
        // The test contract must already hold the asset. Enforce that here.
        require(IERC20(asset).balanceOf(address(this)) >= depositAmount, "balance");

        // The deciding call: depositAsset must not revert under these conditions.
        c.depositAsset(asset, depositAmount);

        // Read the resulting rsETH balance of this test contract.
        address rsethToken = c.lrtConfig().rsETH();
        uint256 rsethBalanceAfter = IERC20(rsethToken).balanceOf(address(this));

        // The general rule: the rsETH balance increase equals the expected mint amount.
        assert(rsethBalanceAfter == expectedMint);
    }
    receive() external payable {}
}

contract InvMutTest {
    C c;

    event AssetDeposit(address asset, uint256 depositAmount, uint256 rsethMintAmount);

    constructor(C _c) {
        c = _c;
    }

    function run(address asset, uint256 depositAmount) public {
        require(depositAmount > 0, "zero");
        require(depositAmount <= c.getAssetCurrentLimit(asset), "limit");
        (bool ok, bytes memory ret) = asset.staticcall(abi.encodeWithSignature("balanceOf(address)", address(this)));
        require(ok && abi.decode(ret, (uint256)) >= depositAmount, "balance");

        (bool ok2, ) = asset.call(abi.encodeWithSignature("approve(address,uint256)", address(c), depositAmount));
        require(ok2, "approve");

        c.depositAsset(asset, depositAmount);

        assert(depositAmount <= c.getAssetCurrentLimit(asset) + c.getTotalAssetDeposits(asset));
    }

    receive() external payable {}
}

contract InvMutTest {
    C internal c;

    constructor(C _c) {
        c = _c;
    }

    receive() external payable {}

    function run(address asset, uint256 depositAmount) public payable {
        require(depositAmount > 0, "zero");

        uint256 beforeTotal = c.getTotalAssetDeposits(asset);
        uint256 beforeLimit = c.getAssetCurrentLimit(asset);
        require(depositAmount <= beforeLimit, "limit");

        (bool ok, bytes memory ret) = asset.staticcall(abi.encodeWithSignature("balanceOf(address)", msg.sender));
        require(ok, "balance read");
        uint256 senderAssetBalance = abi.decode(ret, (uint256));
        require(senderAssetBalance >= depositAmount, "asset balance");

        (bool ok2, bytes memory ret2) = asset.staticcall(abi.encodeWithSignature("allowance(address,address)", msg.sender, address(this)));
        require(ok2, "allowance read");
        uint256 allowed = abi.decode(ret2, (uint256));
        require(allowed >= depositAmount, "allowance");

        uint256 beforeThisAssetBalance = IERC20Balance(asset).balanceOf(address(this));

        c.depositAsset(asset, depositAmount);

        uint256 afterTotal = c.getTotalAssetDeposits(asset);
        uint256 afterLimit = c.getAssetCurrentLimit(asset);
        uint256 afterThisAssetBalance = IERC20Balance(asset).balanceOf(address(this));

        assert(afterTotal >= beforeTotal + depositAmount);
        assert(afterLimit + depositAmount <= beforeLimit);
        assert(afterThisAssetBalance >= beforeThisAssetBalance);
    }

    interface IERC20Balance {
        function balanceOf(address account) external view returns (uint256);
    }
}
